/* voice_fx.js - 机器人音色实时预览(先试后烧) */
const WAV_B64 = "";

const FX = [
  {id:'off',   nm:'关(原声)', d:'不做任何处理',      p:{rf:0,rd:0,cb:16,et:0,eg:0,gn:1,rt:1}},
  {id:'metal', nm:'机械金属', d:'环形调制+颗粒',     p:{rf:120,rd:0.38,cb:10,et:0,eg:0,gn:1,rt:1}},
  {id:'deep',  nm:'电子低沉', d:'降调+软失真',       p:{rf:0,rd:0,cb:13,et:0,eg:0,gn:1.7,rt:0.85}},
  {id:'cyber', nm:'赛博外星', d:'环形+回声+颗粒',    p:{rf:200,rd:0.25,cb:11,et:60,eg:0.30,gn:1,rt:1}},
  {id:'zap',   nm:'电流音',   d:'方波调制+麻颗粒',   p:{rf:55,rd:0.45,cb:9,et:40,eg:0.22,gn:1.1,rt:1,sq:1}},
  {id:'zap2',  nm:'强电流',   d:'低频方波+重颗粒',   p:{rf:33,rd:0.60,cb:7,et:55,eg:0.30,gn:1.3,rt:1,sq:1}},
  {id:'radio', nm:'对讲机',   d:'窄带+像步话机',     p:{rf:0,rd:0,cb:8,et:0,eg:0,gn:1.2,rt:1,bp:1}},
  {id:'space', nm:'深空回声', d:'长回声太空感',      p:{rf:0,rd:0,cb:12,et:240,eg:0.45,gn:1,rt:0.9}}
];const WORKLET = [
'class FxProcessor extends AudioWorkletProcessor {',
'  static get parameterDescriptors(){ return [',
"    {name:'ringFreq',  defaultValue:0,  minValue:0,  maxValue:2000, automationRate:'k-rate'},",
"    {name:'ringDepth', defaultValue:0,  minValue:0,  maxValue:1,    automationRate:'k-rate'},",
"    {name:'crushBits', defaultValue:16, minValue:4,  maxValue:16,   automationRate:'k-rate'},",
"    {name:'gain',      defaultValue:1,  minValue:0.1,maxValue:8,    automationRate:'k-rate'},",
"    {name:'square',    defaultValue:0,  minValue:0,  maxValue:1,    automationRate:'k-rate'}",
'  ];}',
'  constructor(){ super(); this.ph = 0; }',
'  process(inputs, outputs, params){',
'    const out = outputs[0][0]; if(!out) return true;',
'    const inp = inputs[0] && inputs[0][0] ? inputs[0][0] : null;',
'    const rf = params.ringFreq[0], rd = params.ringDepth[0];',
'    const cb = params.crushBits[0], gn = params.gain[0], sq = params.square[0];',
'    const q = Math.pow(2, cb-1);',
'    for(let i=0;i<out.length;i++){',
'      let v = inp ? inp[i] : 0;',
'      if(rd > 0 && rf > 0){',
'        this.ph += 2*Math.PI*rf/sampleRate;',
'        if(this.ph > 2*Math.PI) this.ph -= 2*Math.PI;',
'        const m = sq ? (Math.sin(this.ph) >= 0 ? 1 : -1) : Math.sin(this.ph);',
'        v = v*(1-rd) + v*m*rd;',
'      }',
'      if(cb < 16) v = Math.round(v*q)/q;',
'      v *= gn;',
'      if(v > 1) v = 1; if(v < -1) v = -1;',
'      out[i] = v;',
'    }',
'    return true;',
'  }',
'}',
'registerProcessor("fx-proc", FxProcessor);'
].join('\n');

let actx, worklet, srcNode, delay, fb, hp, lp, an, wavBuf;
let curFx = 'zap';
let bypass = false;   /* true = 源头直连喇叭, 不走效果链(排障用) */
function el(id){ return document.getElementById(id); }
function num(id){ return +el(id).value; }

async function initAudio(){
  if(actx) return;
  actx = new (window.AudioContext||window.webkitAudioContext)();
  const url = URL.createObjectURL(new Blob([WORKLET], {type:'application/javascript'}));
  await actx.audioWorklet.addModule(url);
  worklet = new AudioWorkletNode(actx, 'fx-proc');
  const b64 = WAV_B64.replace(/^data:audio\/wav;base64,/,'');
  const raw = atob(b64), ab = new ArrayBuffer(raw.length), u8 = new Uint8Array(ab);
  for(let i=0;i<raw.length;i++) u8[i] = raw.charCodeAt(i);
  wavBuf = await actx.decodeAudioData(ab);
  hp = actx.createBiquadFilter(); hp.type='highpass'; hp.frequency.value=20;
  lp = actx.createBiquadFilter(); lp.type='lowpass';  lp.frequency.value=20000;
  delay = actx.createDelay(1.0);
  fb = actx.createGain();
  an = actx.createAnalyser(); an.fftSize = 512;
  worklet.connect(hp); hp.connect(lp); lp.connect(an);
  an.connect(delay); an.connect(actx.destination);
  delay.connect(actx.destination); delay.connect(fb); fb.connect(delay);
  applyParams();
}
function stopAll(){ if(srcNode){ try{srcNode.stop();}catch(e){} srcNode=null; } }
function applyParams(){
  if(!worklet) return;
  worklet.parameters.get('ringFreq').value  = num('rf');
  worklet.parameters.get('ringDepth').value = num('rd')/100;
  worklet.parameters.get('crushBits').value = num('cb');
  worklet.parameters.get('gain').value      = num('gn')/100;
  worklet.parameters.get('square').value    = el('w_q').classList.contains('on')?1:0;
  delay.delayTime.value = num('et')/1000;
  fb.gain.value         = num('eg')/100;
  hp.frequency.value    = curFx==='radio' ? 300 : 20;
  lp.frequency.value    = curFx==='radio' ? 3400 : 20000;
}async function play(){
  await initAudio();
  if(actx.state==='suspended') await actx.resume();
  stopAll();
  srcNode = actx.createBufferSource();
  srcNode.buffer = wavBuf;
  srcNode.playbackRate.value = num('rt')/100;
  /* 直连模式 = 排障用: 如果直连有声、走效果链没声, 问题就在效果器那几环 */
  srcNode.connect(bypass ? actx.destination : worklet);
  srcNode.onended = function(){ el('stat').textContent='播放结束'; };
  el('stat').textContent='播放中…';
  srcNode.start();
}

FX.forEach(function(f){
  const d = document.createElement('div');
  d.className = 'fx' + (f.id===curFx?' on':'');
  d.innerHTML = f.nm + '<div class="d">'+f.d+'</div>';
  d.onclick = function(){ curFx=f.id; setSliders(f.p);
    const all = document.querySelectorAll('#fxrow .fx');
    for(const x of all) x.classList.remove('on');
    d.classList.add('on'); applyParams(); };
  el('fxrow').appendChild(d);
  const b = document.createElement('button');
  b.className='btn'; b.textContent=f.nm;
  b.onclick = function(){ curFx=f.id; setSliders(f.p); applyParams();
    const all = document.querySelectorAll('#fxrow .fx');
    let k=0; for(const x of all){ x.classList.toggle('on', FX[k].id===f.id); k++; } };
  el('presets').appendChild(b);
});
function setSliders(p){
  el('rf').value = p.rf||0;
  el('rd').value = Math.round((p.rd||0)*100);
  el('cb').value = p.cb||16;
  el('et').value = p.et||0;
  el('eg').value = Math.round((p.eg||0)*100);
  el('gn').value = Math.round((p.gn||1)*100);
  el('rt').value = Math.round((p.rt||1)*100);
  updLabels(); applyParams();
}
['rf','rd','cb','et','eg','gn','rt'].forEach(function(id){
  el(id).addEventListener('input', function(){ updLabels(); if(actx) applyParams(); });
});
function updLabels(){
  el('v_rf').textContent = num('rf');
  el('v_rd').textContent = num('rd');
  el('v_cb').textContent = num('cb');
  el('v_et').textContent = num('et');
  el('v_eg').textContent = num('eg');
  el('v_gn').textContent = num('gn');
  el('v_rt').textContent = (num('rt')/100).toFixed(2);
}
el('play').onclick = play;
el('stop').onclick = stopAll;
/* ---------- 电平表 ---------- */
let anData = null;
setInterval(function(){
  if(!an || !actx) return;
  if(!anData || anData.length !== an.fftSize) anData = new Float32Array(an.fftSize);
  an.getFloatTimeDomainData(anData);
  let peak = 0;
  for(let i=0;i<anData.length;i++){ const a = Math.abs(anData[i]); if(a > peak) peak = a; }
  el('lvl').style.width = Math.min(100, Math.round(peak*140)) + '%';
}, 120);

/* ---------- 直连开关 ---------- */
el('direct').onclick = function(){
  bypass = !bypass;
  this.textContent = '绕过效果直连: ' + (bypass ? '开' : '关');
  if(srcNode){ stopAll(); play(); }
};

/* ---------- 参数导出 ---------- */
function exportParams(){
  return JSON.stringify({
    fx: curFx,
    rf: num('rf'), rd: num('rd')/100, cb: num('cb'),
    et: num('et'), eg: num('eg')/100,
    gn: num('gn')/100, rt: num('rt')/100,
    sq: el('w_q').classList.contains('on') ? 1 : 0
  });
}
function refreshExport(){ el('exp').value = exportParams(); }
setInterval(refreshExport, 400);
refreshExport();
el('copyexp').onclick = function(){
  el('exp').select();
  try { document.execCommand('copy'); this.textContent = '已复制 ✓';
        setTimeout(function(el2){ return function(){ el2.textContent = '复制参数'; }; }(this), 1200); }
  catch(e){ /* 手动全选复制也可以 */ }
};